  init() {
    console.log("MB INA Platform Engine Initializing (M2 & M3 Active)...");
    this.initSession();
    this.renderView();
    this.initTheme();
    this.bindAdminTabs();

    // Fetch data asynchronously in background without blocking page load spinner!
    setTimeout(() => {
      this.fetchM2Data();
      this.fetchData();
      this.fetchM5Data();
      this.fetchDonationData();
      this.renderTestimonials();
    }, 20);
  },

  initSession() {
    const savedUser = localStorage.getItem('mbina_session_user');
    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        if (u && u.role && u.role !== 'GUEST') {
          this.currentRole = u.role;
          this.currentUser = u;

          // Recalculate live contribution & tier on session init
          const realTotal = this.getMemberTotalContribution(this.currentUser);
          const realTierCalc = this.calculateMemberTier(realTotal);
          this.currentUser.totalDonation = realTotal;
          this.currentUser.tier = realTierCalc.tier;
          localStorage.setItem('mbina_session_user', JSON.stringify(this.currentUser));
          return;
        }
      } catch (e) {
        console.error("Session parse error:", e);
      }
    }

    // STRICT ZERO-TRUST SECURITY: Unauthenticated users are ALWAYS 'GUEST'
    this.currentRole = 'GUEST';
    this.currentUser = { id: 'usr_guest', name: 'Pengunjung', username: 'guest', email: '', role: 'GUEST' };
  },

  navigateToHome() {
    document.querySelectorAll('.view-container').forEach(el => el.style.display = 'none');
    const landingView = document.getElementById('view-landing-page');
    if (landingView) landingView.style.display = 'block';

    const sidebar = document.getElementById('app-sidebar');
    const btnHamburger = document.getElementById('btn-hamburger-toggle');
    if (sidebar) sidebar.style.display = 'none';
    if (btnHamburger) btnHamburger.style.display = 'none';
    document.body.classList.remove('yt-has-sidebar');

    window.scrollTo({ top: 0, behavior: 'smooth' });
  },

  openPortalAdmin() {
    const isAdminRole = ['SUPER_ADMIN', 'PRESIDEN', 'SEKRETARIS_PUSAT', 'BENDAHARA_PUSAT', 'PENGURUS_PUSAT', 'ADMIN_ORGANISASI', 'PENGURUS_KLUB'].includes(this.currentRole);
    if (this.currentRole === 'GUEST') {
      AuthEngine.openModal('modal-login');
      alert('🔒 Akses Terbatas: Silakan Login terlebih dahulu dengan akun Super Admin / Pengurus!');
    } else if (!isAdminRole) {
      alert('⚠️ Akses Ditolak: Halaman Portal Admin & Verifikasi hanya untuk Pengurus Pusat & Admin Organisasi MB INA.');
    } else {
      document.querySelectorAll('.view-container').forEach(el => el.style.display = 'none');
      const adminView = document.getElementById('view-admin-dashboard');
      if (adminView) {
        adminView.style.display = 'block';

        const sidebar = document.getElementById('app-sidebar');
        const btnHamburger = document.getElementById('btn-hamburger-toggle');
        if (sidebar) sidebar.style.display = 'flex';
        if (btnHamburger) btnHamburger.style.display = 'inline-flex';
        document.body.classList.add('yt-has-sidebar');

        this.switchAdminTab(this.activeAdminTab);
      }
    }
  },

