  async saveClubFromModal(event) {
    event.preventDefault();
    const id = document.getElementById('edit-club-id').value;
    const name = document.getElementById('edit-club-name').value.trim();
    const code = document.getElementById('edit-club-code').value.trim();
    const type = document.getElementById('edit-club-type').value;
    const region = document.getElementById('edit-club-region').value;
    const city = document.getElementById('edit-club-city').value.trim();
    const member_count = parseInt(document.getElementById('edit-club-member-count').value || 50);
    const ketua_umum = document.getElementById('edit-club-ketua').value.trim();
    const contact_person = document.getElementById('edit-club-cp').value.trim();
    const contact_phone = document.getElementById('edit-club-phone').value.trim();
    const founded_year = parseInt(document.getElementById('edit-club-year').value || 2004);
    const description = document.getElementById('edit-club-desc').value.trim();

    const action = id ? 'update_m2_club' : 'create_m2_club';

    try {
      const res = await fetch(`api.php?action=${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, name, code, type, region, city, member_count, ketua_umum, contact_person, contact_phone, founded_year, description })
      });
      const data = await res.json();
      alert('🎉 ' + data.message);
      AuthEngine.closeAllModals();
      await this.fetchM2Data();
      this.renderM2Clubs();
      this.renderClubsList();
    } catch (e) {
      alert('Gagal menyimpan Klub!');
    }
  },

  async deleteClub(id) {
    if (!confirm('Apakah Anda yakin ingin menghapus Klub/Chapter ini dari Supabase Cloud Database?')) return;
    try {
      const res = await fetch('api.php?action=delete_m2_club', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id })
      });
      const data = await res.json();
      alert(data.message);
      await this.fetchM2Data();
      this.renderM2Clubs();
      this.renderClubsList();
    } catch (e) {
      alert('Gagal menghapus Klub!');
    }
  },

  async showClubDetail(clubId) {
    try {
      const res = await fetch(`api.php?action=get_m2_club_detail&club_id=${clubId}`).then(r => r.json());
      if (res.success && res.club) {
        const c = res.club;
        alert(`ℹ️ DETAIL KLUB MB INA:\n\nNama Klub: ${c.name} (${c.code})\nRegion: ${c.region}\nDomisili: ${c.city}\nTipe: ${c.type}\nTotal Member: ${c.member_count} Anggota\nStatus: AKTIF / VERIFIED`);
      }
    } catch (e) {
      alert('Gagal memuat detail klub!');
    }
  },

  getOfficialMemberId(user) {
    if (!user) return 'MBINA-HQ-2026-000001';
    
    if (typeof user === 'string') {
      if (user.startsWith('MBINA-')) return user;
      const found = (this.users || []).find(u => u.id === user || u.username === user || u.memberId === user || u.member_id === user)
                 || (window.M6Engine && window.M6Engine.sampleMembersDb ? window.M6Engine.sampleMembersDb.find(m => m.id === user || m.member_id === user) : null);
      if (found) return this.getOfficialMemberId(found);
      return 'MBINA-JAM-2026-000001';
    }

    if (user.member_id && user.member_id.startsWith('MBINA-')) return user.member_id;
    if (user.memberId && user.memberId.startsWith('MBINA-')) return user.memberId;

    const id = (user.id || '').toLowerCase();
    const uname = (user.username || '').toLowerCase();
    const pId = (user.province_id || user.provinceId || '').toLowerCase();
    const pName = (user.province || user.province_name || '').toLowerCase();
    const cName = (user.city || '').toLowerCase();

    if (id.includes('000001') || id.includes('derist') || uname.includes('derist') || id === 'usr_superadmin') return 'MBINA-HQ-2026-000001';
    if (id.includes('000002') || id.includes('raymond') || uname.includes('raymond')) return 'MBINA-HQ-2026-000002';
    if (id.includes('presiden') || uname.includes('presiden') || id.includes('000004')) return 'MBINA-HQ-2026-000004';
    if (id.includes('denny') || uname.includes('denny') || id.includes('m3_005')) return 'MBINA-JKT-2026-000009';
    if (id.includes('andi_wijaya') || uname.includes('andi_wijaya') || id.includes('m3_004')) return 'MBINA-MED-2026-000008';
    if (uname === 'andi_pratama' || id === 'usr_m3_001') return 'MBINA-JKT-2026-000005';
    if (uname === 'budi_santoso' || id === 'usr_m3_002') return 'MBINA-BDG-2026-000006';
    if (uname === 'siti_rahayu' || id === 'usr_m3_003') return 'MBINA-SBY-2026-000007';

    // Pemetaan Kode Wilayah Berdasarkan Provinsi / Kota
    let region = 'JAM';
    if (pId === 'prov_jam' || pName.includes('jambi') || cName.includes('jambi')) region = 'JAM';
    else if (pId === 'prov_jkt' || pName.includes('jakarta') || cName.includes('jakarta')) region = 'JKT';
    else if (pId === 'prov_jbr' || pName.includes('jawa barat') || cName.includes('bandung')) region = 'JBR';
    else if (pId === 'prov_jtg' || pName.includes('jawa tengah') || cName.includes('semarang') || cName.includes('solo')) region = 'JTG';
    else if (pId === 'prov_jtm' || pName.includes('jawa timur') || cName.includes('surabaya')) region = 'JTM';
    else if (pId === 'prov_sum' || pName.includes('sumatera utara') || cName.includes('medan')) region = 'SUM';
    else if (pId === 'prov_sbr' || pName.includes('sumatera barat') || cName.includes('padang')) region = 'SBR';
    else if (pId === 'prov_ria' || pName.includes('riau') || cName.includes('pekanbaru')) region = 'RIA';
    else if (pId === 'prov_btn' || pName.includes('banten') || cName.includes('tangerang')) region = 'BTN';
    else if (pId === 'prov_diy' || pName.includes('yogyakarta') || cName.includes('jogja')) region = 'DIY';
    else if (pId === 'prov_bli' || pName.includes('bali') || cName.includes('denpasar')) region = 'BLI';
    else if (pId && pId.startsWith('prov_')) region = pId.replace('prov_', '').toUpperCase();
    else if (user.city && user.city.length >= 3) region = user.city.substring(0, 3).toUpperCase();

    const cleanNum = (id.replace(/[^0-9]/g, '') || String(Math.floor(Math.random() * 800 + 100))).padStart(6, '0');
    return `MBINA-${region}-2026-${cleanNum}`;
  },

