  openEditPublishedEventModal() {
    const ev = this.publishedEvents[0];
    if (!ev) return;

    const ti = document.getElementById('m6-edit-pub-title');
    const de = document.getElementById('m6-edit-pub-desc');
    const st = document.getElementById('m6-edit-pub-start');
    const en = document.getElementById('m6-edit-pub-end');
    const lo = document.getElementById('m6-edit-pub-location');

    if (ti) ti.value = ev.title;
    if (de) de.value = ev.description;
    if (st) st.value = ev.start_date || '2026-09-12T08:00';
    if (en) en.value = ev.end_date || '2026-09-14T18:00';
    if (lo) lo.value = ev.location;

    AuthEngine.openModal('modal-m6-edit-event-published');
  },

  savePublishedEventChanges(e) {
    e.preventDefault();
    const ev = this.publishedEvents[0];
    if (!ev) return;

    const title = document.getElementById('m6-edit-pub-title')?.value.trim();
    const desc  = document.getElementById('m6-edit-pub-desc')?.value.trim();
    const start = document.getElementById('m6-edit-pub-start')?.value;
    const end   = document.getElementById('m6-edit-pub-end')?.value;
    const loc   = document.getElementById('m6-edit-pub-location')?.value.trim();

    if (!title || !desc) { alert('⚠️ Judul & Deskripsi wajib diisi!'); return; }

    ev.title = title;
    ev.description = desc;
    ev.start_date = start;
    ev.end_date = end;
    ev.location = loc;

    const formatDt = (str) => {
      if (!str) return '';
      const d = new Date(str);
      return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }) + ', ' + d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
    };

    ev.start_formatted = formatDt(start);
    ev.end_formatted   = formatDt(end);

    // Update 6.3 Card UI
    const elTitle = document.getElementById('m6-pub-evt-title');
    const elDesc  = document.getElementById('m6-pub-evt-desc');
    const elStart = document.getElementById('m6-pub-evt-start-fmt');
    const elEnd   = document.getElementById('m6-pub-evt-end-fmt');
    const elLoc   = document.getElementById('m6-pub-evt-location');

    if (elTitle) elTitle.textContent = ev.title;
    if (elDesc)  elDesc.textContent  = ev.description;
    if (elStart) elStart.textContent = ev.start_formatted;
    if (elEnd)   elEnd.textContent   = ev.end_formatted;
    if (elLoc)   elLoc.textContent   = ev.location;

    // Sync to M1 Dashboard Calendar
    if (window.AppEngine) window.AppEngine.renderAdminCalendarEvents();

    AuthEngine.closeModal('modal-m6-edit-event-published');
    alert('✅ Deskripsi dan waktu event published berhasil diperbarui & disinkronkan ke Kalender Dashboard (Modul M1)!');
  },

