  verifyParticipantPayment(partId, newStatus) {
    const part = (this.data.participants || []).find(p => p.id === partId) || (this.getParticipantsForEvent(this.selectedEventId) || []).find(p => p.id === partId);
    if (!part) return;

    if (newStatus === 'REJECTED') {
      const reason = prompt('Masukkan alasan penolakan bukti pembayaran:', 'Bukti transfer tidak sesuai atau kurang jelas');
      if (reason === null) return;
      part.status = 'REJECTED';
      part.rejection_reason = reason;
      alert('❌ Pendaftaran ' + part.name + ' ditolak dengan alasan: ' + reason);
    } else if (newStatus === 'VERIFIED') {
      part.status = 'VERIFIED';
      part.payment_status = 'PAID';
      part.qr_code = 'QR-EVT-2026-001-' + (part.name || 'MBINA').substring(0, 4).toUpperCase();

      // 1. Akumulasi Biaya Tiket Event ke Donasi/Kontribusi Member & Hitung Ulang Tier Real-time!
      const htmAmount = Number(part.htm || 400000);
      const targetMid = part.member_id || '';
      const targetName = (part.name || '').toLowerCase();

      const updateMemberContrib = (m) => {
        if (!m) return;
        if (!m._verifiedEvents) m._verifiedEvents = {};
        if (!m._verifiedEvents[partId]) {
          m._verifiedEvents[partId] = true;
          const currentDon = Number(m.total_donation || m.totalDonation || m.total_contribution || 0);
          const newDon = currentDon + htmAmount;
          m.total_donation = newDon;
          m.totalDonation = newDon;
          m.total_contribution = newDon;

          if (window.AppEngine && typeof window.AppEngine.calculateMemberTier === 'function') {
            const tierRes = window.AppEngine.calculateMemberTier(newDon);
            m.tier = tierRes.tier;
          }
        }
      };

      // Update di M3 Members
      if (window.AppEngine && window.AppEngine.m3Data && Array.isArray(window.AppEngine.m3Data.members)) {
        window.AppEngine.m3Data.members.forEach(m => {
          if ((m.member_id && m.member_id === targetMid) || (m.name && m.name.toLowerCase() === targetName)) {
            updateMemberContrib(m);
          }
        });
      }

      // Update di Users
      if (window.AppEngine && Array.isArray(window.AppEngine.users)) {
        window.AppEngine.users.forEach(u => {
          if ((u.memberId && u.memberId === targetMid) || (u.member_id && u.member_id === targetMid) || (u.name && u.name.toLowerCase() === targetName)) {
            updateMemberContrib(u);
          }
        });
      }

      // Update di Sample Members DB
      if (Array.isArray(this.sampleMembersDb)) {
        this.sampleMembersDb.forEach(s => {
          if ((s.id && s.id === targetMid) || (s.name && s.name.toLowerCase() === targetName)) {
            updateMemberContrib(s);
          }
        });
      }

      // Update di Active Session User jika sama
      if (window.AppEngine && window.AppEngine.currentUser) {
        const cur = window.AppEngine.currentUser;
        if ((cur.member_id && cur.member_id === targetMid) || (cur.name && cur.name.toLowerCase() === targetName)) {
          updateMemberContrib(cur);
          localStorage.setItem('mbina_session_user', JSON.stringify(cur));
        }
      }

      // Live update DOM modal edit jika sedang terbuka
      const activeEditId = document.getElementById('m3-edit-id')?.value;
      if (activeEditId && (activeEditId === targetMid || activeEditId === part.id)) {
        const targetObj = (window.AppEngine && window.AppEngine.m3Data && window.AppEngine.m3Data.members) ? window.AppEngine.m3Data.members.find(x => x.id === activeEditId || x.member_id === targetMid) : null;
        if (targetObj) {
          const updatedDon = Number(targetObj.total_donation || targetObj.totalDonation || 0);
          const donTxt = document.getElementById('m3-edit-donation-text');
          if (donTxt) donTxt.innerText = `(Donasi/Event: Rp ${new Intl.NumberFormat('id-ID').format(updatedDon)})`;
          const tierTxt = document.getElementById('m3-edit-tier-text');
          if (tierTxt) tierTxt.innerText = `${targetObj.tier} MEMBER`;
        }
      }

      // Refresh M3 Member Table
      if (window.AppEngine) {
        if (typeof window.AppEngine.renderM3MemberList === 'function') window.AppEngine.renderM3MemberList();
        if (typeof window.AppEngine.syncCurrentUserStatusFromList === 'function') window.AppEngine.syncCurrentUserStatusFromList();
      }

      alert('✅ PEMBAYARAN PESERTA TERVERIFIKASI & DITERIMA!\n\nNama Peserta: ' + part.name + '\nMember ID / KTA: ' + (part.member_id || 'MBINA-HQ-2026-000001') + '\nNominal Tiket: Rp ' + new Intl.NumberFormat('id-ID').format(htmAmount) + '\nStatus Bayar: 🟢 VERIFIED (Diterima)\n\nAkumulasi Donasi/Event pada Biodata Member telah otomatis bertambah (+Rp ' + new Intl.NumberFormat('id-ID').format(htmAmount) + ') & Tier Keanggotaan terupdate real-time!');
    } else {
      part.status = newStatus;
    }

    if (!this.participantStatusOverrides) this.participantStatusOverrides = {};
    this.participantStatusOverrides[partId] = part.status;
    if (part.member_id) this.participantStatusOverrides[part.member_id] = part.status;
    if (part.memberId) this.participantStatusOverrides[part.memberId] = part.status;

    try {
      localStorage.setItem('mbina_participant_status_overrides', JSON.stringify(this.participantStatusOverrides));
    } catch(e) {}

    // POST to Supabase Database API
    fetch('api.php?action=verify_participant_payment', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ participant_id: partId, id: partId, member_id: part.member_id || '', status: part.status })
    }).catch(err => console.warn('API participant verify sync error:', err));

    // Trigger immediate re-render of Member Portal and M3 List
    if (window.AppEngine) {
      if (typeof window.AppEngine.populateMemberPortalData === 'function') window.AppEngine.populateMemberPortalData();
      if (typeof window.AppEngine.renderM3MemberList === 'function') window.AppEngine.renderM3MemberList();
    }

    this.renderParticipantsTable();
  },

