  verifyPayment(participantId, isApproved) {
    let participant = null;
    if (this.data.participants && this.data.participants.length > 0) {
      participant = this.data.participants.find(p => p.id === participantId);
    }
    
    if (!participant) {
      ['EVT-2026-001', 'EVT-2026-002', 'EVT-2026-003'].forEach(evtId => {
        const list = this.getParticipantsForEvent(evtId);
        const found = list.find(p => p.id === participantId);
        if (found) participant = found;
      });
    }

    const newStatus = isApproved ? 'VERIFIED' : 'REJECTED';
    if (participant) {
      participant.status = newStatus;
    }

    if (!this.participantStatusOverrides) this.participantStatusOverrides = {};
    this.participantStatusOverrides[participantId] = newStatus;

    if (isApproved) {
      alert('🎉 VERIFIKASI PEMBAYARAN TIKET BERHASIL!\n\nPembayaran peserta ' + (participant ? (participant.name || participantId) : participantId) + ' telah DITERIMA (🟢 VERIFIED).\nKartu Undangan Event & QR Code Resmi otomatis aktif!');
    } else {
      alert('🔴 VERIFIKASI PEMBAYARAN TIKET DITOLAK!\n\nPembayaran peserta ' + (participant ? (participant.name || participantId) : participantId) + ' telah DITOLAK (🔴 REJECTED).');
    }

    this.renderPublishPage();
  },

