  printOfficialProposal() {
    const printArea = document.getElementById('m6-official-proposal-print-area');
    if (!printArea) return;

    const printWin = window.open('', '_blank', 'width=950,height=850');
    if (!printWin) {
      window.print();
      return;
    }

    printWin.document.write(`
      <!DOCTYPE html>
      <html>
      <head>
        <title>PROPOSAL EVENT RESMI MB CLUB INDONESIA - EVT-2026-001</title>
        <style>
          body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 30px; background: #fff; color: #000; margin: 0; }
          table { border-collapse: collapse; width: 100%; }
          @page { size: A4 portrait; margin: 15mm; }
          @media print {
            body { padding: 0; }
          }
        </style>
      </head>
      <body>
        ${printArea.innerHTML}
        <script>
          window.onload = function() {
            window.focus();
            window.print();
            setTimeout(function() { window.close(); }, 500);
          };
        </script>
      </body>
      </html>
    `);
    printWin.document.close();
  },

