    const tabId = this.currentSponsorInnerTab;
    if (tabId === '641') this.renderSponsorPackagesTable();
    if (tabId === '643') this.renderSponsorConfirmTable();
    if (tabId === '644') this.renderSponsorBannerSetup();
    if (tabId === '645') this.renderSponsorDashboardModule();
    if (tabId === '646') this.renderSponsorEffectivenessReport();
