  // ─── NAVIGATION ──────────────────────────────────────────────────
  switchSubtab: function(tab) {
    this.currentSubTab = tab;
    ['m8-sub-81','m8-sub-82','m8-sub-83','m8-sub-84'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });
    const map = { '8_1_endorse': 'm8-sub-81', '8_2_iklan': 'm8-sub-82', '8_3_analitik': 'm8-sub-83', '8_3_lapkeu': 'm8-sub-83', '8_4_pajak': 'm8-sub-84' };
    const target = document.getElementById(map[tab] || 'm8-sub-81');
    if (target) target.style.display = 'block';
    ['81','82','83','84'].forEach(n => {
      const btn = document.getElementById(`m8-subtab-btn-${n}`);
      if (btn) btn.classList.remove('active');
    });
    const tabNumMap = { '8_1_endorse': '81', '8_2_iklan': '82', '8_3_analitik': '83', '8_3_lapkeu': '83', '8_4_pajak': '84' };
    const activeBtn = document.getElementById(`m8-subtab-btn-${tabNumMap[tab] || '81'}`);
    if (activeBtn) activeBtn.classList.add('active');
  },

  switchEndorseTab: function(tab) {
    this.currentEndorseTab = tab;
    const pkgEl = document.getElementById('m8-endorse-packages');
    const ctrEl = document.getElementById('m8-endorse-contracts');
    const rptEl = document.getElementById('m8-endorse-report');

    if (tab === 'packages' || tab === 'all') {
      if (pkgEl) pkgEl.style.display = 'block';
      if (ctrEl) ctrEl.style.display = 'block';
      if (rptEl) rptEl.style.display = 'none';
    } else if (tab === 'contracts') {
      if (pkgEl) pkgEl.style.display = 'none';
      if (ctrEl) ctrEl.style.display = 'block';
      if (rptEl) rptEl.style.display = 'none';
    } else if (tab === 'report') {
      if (pkgEl) pkgEl.style.display = 'none';
      if (ctrEl) ctrEl.style.display = 'none';
      if (rptEl) rptEl.style.display = 'block';
    }

    ['packages','contracts','report'].forEach(t => {
      const btn = document.getElementById(`m8-e-tab-${t}`);
      if (btn) { btn.style.background = ''; btn.style.color = ''; btn.style.borderColor = ''; }
    });
    const activeBtn = document.getElementById(`m8-e-tab-${tab}`);
    if (activeBtn) { activeBtn.style.background = 'rgba(245,158,11,0.2)'; activeBtn.style.color = 'var(--accent-gold)'; activeBtn.style.borderColor = 'var(--accent-gold)'; }
  },

