  // ─── 8.4 PAJAK ───────────────────────────────────────────────────
  recalcTax: function() {
    const nilai   = parseInt(document.getElementById('m8-tax-nilai')?.value || '0');
    const ppnRate = parseFloat(document.getElementById('m8-tax-ppn-rate')?.value || '11');
    const pphRate = parseFloat(document.getElementById('m8-tax-pph-rate')?.value || '2');
    const ppn = Math.round(nilai * (ppnRate / 100));
    const pph = Math.round(nilai * (pphRate / 100));
    const totalTax = ppn + pph;
    const totalTagihan = nilai + ppn;
    const fmt = v => 'Rp ' + new Intl.NumberFormat('id-ID').format(v);
    const setEl = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    setEl('m8-res-nilai', fmt(nilai));
    setEl('m8-res-ppn', fmt(ppn));
    setEl('m8-res-pph', fmt(pph));
    setEl('m8-res-total-tax', fmt(totalTax));
    setEl('m8-res-total', fmt(totalTagihan));
    // Update rate labels
    const ppnLbl = document.querySelector('#m8-tax-result div:nth-child(2) span:first-child');
    const pphLbl = document.querySelector('#m8-tax-result div:nth-child(3) span:first-child');
    if (ppnLbl) ppnLbl.textContent = `PPN (${ppnRate}%)`;
    if (pphLbl) pphLbl.textContent = `PPh (${pphRate}%)`;
  },

  recalcInvoice: function() {
    const amount  = parseInt(document.getElementById('inv-amount')?.value || '0');
    const ppnRate = parseFloat(document.getElementById('inv-ppn-rate')?.value || '11');
    const ppn = Math.round(amount * (ppnRate / 100));
    const total = amount + ppn;
    const fmt = v => 'Rp ' + new Intl.NumberFormat('id-ID').format(v);
    const setEl = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    setEl('inv-res-amount', fmt(amount));
    setEl('inv-res-ppn', fmt(ppn));
    setEl('inv-res-total', fmt(total));
  },

  submitTaxInvoice: async function(e) {
    e.preventDefault();
    const partnerName = document.getElementById('inv-partner')?.value?.trim() || '';
    const type   = document.getElementById('inv-type')?.value || 'OTHER';
    const amount = parseInt(document.getElementById('inv-amount')?.value || '0');
    const ppnRate = parseFloat(document.getElementById('inv-ppn-rate')?.value || '11');
    const dueDate = document.getElementById('inv-due')?.value || '';
    const notes  = document.getElementById('inv-notes')?.value?.trim() || '';
    if (!partnerName || amount <= 0) { alert('❌ Nama mitra dan nilai wajib diisi!'); return; }
    try {
      const btn = document.querySelector('#form-tax-invoice button[type="submit"]');
      if (btn) { btn.disabled = true; btn.textContent = '⏳ Generating...'; }
      const res = await fetch('api.php?action=generate_invoice', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, partner_name: partnerName, amount, ppn_rate: ppnRate, due_date: dueDate, notes })
      }).then(r => r.json());
      if (res && res.success) {
        alert(`✅ Invoice ${res.invoice_number} berhasil di-generate!\nTotal: Rp ${new Intl.NumberFormat('id-ID').format(res.total_amount)}`);
        document.getElementById('form-tax-invoice')?.reset();
        this.recalcInvoice();
      } else {
        alert(`❌ Gagal: ${res?.message || 'Error'}`);
      }
    } catch (err) {
      alert(`❌ Connection error: ${err.message}`);
    } finally {
      const btn = document.querySelector('#form-tax-invoice button[type="submit"]');
      if (btn) { btn.disabled = false; btn.textContent = '💾 GENERATE INVOICE'; }
    }
  },

