        '<div class="glass-card" style="padding:16px;border-left:3px solid #22c55e;text-align:center;"><div style="font-size:1.2rem;font-weight:900;color:#22c55e;">' + fmt(45000000) + '</div><div style="font-size:0.75rem;color:var(--text-muted);margin-top:4px;">Total Donasi Event 2026</div></div>' +
        '<div class="glass-card" style="padding:16px;border-left:3px solid var(--accent-gold);text-align:center;"><div style="font-size:1rem;font-weight:900;color:var(--accent-gold);">' + fmt(15000000) + '</div><div style="font-size:0.75rem;color:var(--text-muted);margin-top:4px;">Donasi Terbesar</div><div style="font-size:0.7rem;color:var(--text-muted);margin-top:2px;">Charity Run</div></div>' +
        '<div class="glass-card" style="padding:16px;border-left:3px solid #3b82f6;text-align:center;"><div style="font-size:1.2rem;font-weight:900;color:#3b82f6;">5</div><div style="font-size:0.75rem;color:var(--text-muted);margin-top:4px;">Event dengan Donasi</div></div>' +
        '</div>';
