  // ─── 9.5 FINANCIAL REPORT ─────────────────────────────────────────
  renderFinancialReport: function() {
    var fmt = function(v) { return 'Rp ' + new Intl.NumberFormat('id-ID').format(v); };
    var incomes = this.data.transactions.filter(function(t){ return t.type === 'INCOME'; });
    var expenses = this.data.transactions.filter(function(t){ return t.type === 'EXPENSE'; });
    var totalIncome = incomes.reduce(function(s,t){ return s + parseInt(t.amount||0); }, 0);
    var totalExpense = expenses.reduce(function(s,t){ return s + parseInt(t.amount||0); }, 0);
    var netProfit = totalIncome - totalExpense;

    var isEl = document.getElementById('m9-income-statement-body');
    if(isEl) {
      var incomeRows = incomes.map(function(t) {
        return '<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:0.78rem;">' +
          '<span style="color:var(--text-muted);">' + t.category + '</span><span style="font-weight:700;">' + fmt(t.amount) + '</span></div>';
      }).join('');
      var expenseRows = expenses.map(function(t) {
        return '<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:0.78rem;">' +
          '<span style="color:var(--text-muted);">' + t.category + '</span><span style="font-weight:700;color:#f87171;">(' + fmt(t.amount) + ')</span></div>';
      }).join('');
      isEl.innerHTML = '<div style="font-size:0.72rem;font-weight:800;color:#22c55e;letter-spacing:1px;margin-bottom:10px;border-bottom:1px solid rgba(34,197,94,0.3);padding-bottom:6px;">PENDAPATAN</div>' +
        incomeRows +
        '<div style="display:flex;justify-content:space-between;padding:8px 0;border-top:2px solid rgba(34,197,94,0.4);margin-top:6px;"><span style="font-weight:800;color:#22c55e;">TOTAL</span><span style="font-weight:900;color:#22c55e;">' + fmt(totalIncome) + '</span></div>' +
        '<div style="margin-top:16px;font-size:0.72rem;font-weight:800;color:#ef4444;letter-spacing:1px;margin-bottom:10px;border-bottom:1px solid rgba(239,68,68,0.3);padding-bottom:6px;">BEBAN</div>' +
        expenseRows +
        '<div style="display:flex;justify-content:space-between;padding:8px 0;border-top:2px solid rgba(239,68,68,0.4);margin-top:6px;"><span style="font-weight:800;color:#ef4444;">TOTAL BEBAN</span><span style="font-weight:900;color:#ef4444;">(' + fmt(totalExpense) + ')</span></div>' +
        '<div style="display:flex;justify-content:space-between;padding:12px;background:rgba(34,197,94,0.1);border-radius:8px;border:1px solid rgba(34,197,94,0.3);margin-top:12px;"><span style="font-weight:900;color:#fff;">LABA BERSIH</span><span style="font-weight:900;color:#22c55e;font-size:1.05rem;">' + fmt(netProfit) + '</span></div>';
    }

    var colors = ['#f59e0b','#3b82f6','#a855f7','#22c55e','#f97316','#06b6d4','#ec4899'];
    var rbsEl = document.getElementById('m9-revenue-by-source');
    if(rbsEl) {
      rbsEl.innerHTML = incomes.map(function(t, i) {
        var pct = totalIncome > 0 ? ((parseInt(t.amount||0) / totalIncome) * 100).toFixed(1) : 0;
        return '<div style="margin-bottom:12px;">' +
          '<div style="display:flex;justify-content:space-between;margin-bottom:4px;font-size:0.78rem;">' +
          '<span style="color:var(--text-muted);">' + t.category + '</span>' +
          '<span style="font-weight:700;color:' + colors[i%colors.length] + ';">' + pct + '%</span></div>' +
          '<div style="background:rgba(255,255,255,0.08);border-radius:4px;height:8px;overflow:hidden;">' +
          '<div style="height:100%;width:' + pct + '%;background:' + colors[i%colors.length] + ';border-radius:4px;"></div>' +
          '</div></div>';
      }).join('');
    }

    var bvaEl = document.getElementById('m9-budget-actual-body');
    if(bvaEl) {
      var budgets = [
        { category: 'Sponsorship', budget: 40000000, actual: 37500000 },
        { category: 'Tiket Event', budget: 20000000, actual: 15000000 },
        { category: 'Endorse', budget: 30000000, actual: 35000000 },
        { category: 'Iklan Digital', budget: 8000000, actual: 5000000 },
        { category: 'Iuran Member', budget: 10000000, actual: 12000000 }
      ];
      var rows = budgets.map(function(b) {
        var variance = b.actual - b.budget;
        var pct = ((b.actual / b.budget) * 100).toFixed(0);
        var isOver = variance >= 0;
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">' +
          '<td style="padding:10px 12px;font-weight:700;">' + b.category + '</td>' +
          '<td style="padding:10px 12px;text-align:right;color:var(--text-muted);">' + fmt(b.budget) + '</td>' +
          '<td style="padding:10px 12px;text-align:right;font-weight:700;">' + fmt(b.actual) + '</td>' +
          '<td style="padding:10px 12px;text-align:right;font-weight:700;color:' + (isOver?'#22c55e':'#ef4444') + ';">' + (isOver?'+':'') + fmt(Math.abs(variance)) + '</td>' +
          '<td style="padding:10px 12px;text-align:center;"><span style="background:' + (isOver?'rgba(34,197,94,0.15)':'rgba(239,68,68,0.15)') + ';color:' + (isOver?'#22c55e':'#ef4444') + ';padding:2px 8px;border-radius:4px;font-size:0.72rem;font-weight:700;">' + pct + '%</span></td>' +
          '</tr>';
      }).join('');
      bvaEl.innerHTML = '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.8rem;">' +
        '<thead><tr style="background:rgba(245,158,11,0.15);">' +
        '<th style="padding:10px 12px;text-align:left;color:var(--accent-gold);border-bottom:1px solid rgba(245,158,11,0.3);">Kategori</th>' +
        '<th style="padding:10px 12px;text-align:right;color:var(--accent-gold);border-bottom:1px solid rgba(245,158,11,0.3);">Budget</th>' +
        '<th style="padding:10px 12px;text-align:right;color:var(--accent-gold);border-bottom:1px solid rgba(245,158,11,0.3);">Aktual</th>' +
        '<th style="padding:10px 12px;text-align:right;color:var(--accent-gold);border-bottom:1px solid rgba(245,158,11,0.3);">Variance</th>' +
        '<th style="padding:10px 12px;text-align:center;color:var(--accent-gold);border-bottom:1px solid rgba(245,158,11,0.3);">Status</th>' +
        '</tr></thead><tbody>' + rows + '</tbody></table></div>';
    }
  },

