        '<div class="glass-card" style="padding:16px;border-left:3px solid #22c55e;text-align:center;"><div style="font-size:1.8rem;font-weight:900;color:#22c55e;">' + this.data.forumStats.length + '</div><div style="font-size:0.75rem;color:var(--text-muted);margin-top:4px;">Club Aktif Forum</div></div>' +
        '<div class="glass-card" style="padding:16px;border-left:3px solid #a855f7;text-align:center;"><div style="font-size:1.8rem;font-weight:900;color:#a855f7;">' + (totalThreads > 0 ? (totalReplies/totalThreads).toFixed(1) : 0) + '</div><div style="font-size:0.75rem;color:var(--text-muted);margin-top:4px;">Avg Reply/Thread</div></div>';
